<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,errorText} from '@/lib/api'
import {can} from '@/lib/auth'
import {dateTime,pretty} from '@/lib/format'
import AiImportLauncher from '@/features/ai/AiImportLauncher.vue'
import {aiList,enc,jobLabels,taskLabels,verificationLabel,type AIRecord} from '@/features/ai/helpers'
const router=useRouter(),route=useRoute(),models=ref<AIRecord[]>([]),jobs=ref<AIRecord[]>([]),error=ref(''),loading=ref(false),busy=ref(false),query=ref(''),tab=ref('models'),selected=ref<AIRecord>(),detailTab=ref('overview'),peerId=ref(''),peers=ref<AIRecord[]>([]),binding=ref<AIRecord>(),plan=ref<AIRecord>()
const visible=computed(()=>models.value.filter(m=>!query.value||[m.manufacturer,m.modelName,m.version,m.firmwareRange].join(' ').toLowerCase().includes(query.value.toLowerCase())))
const mayImport=computed(()=>can('profile:write'))
async function load(){loading.value=true;error.value='';try{models.value=await aiList('/api/v1/device-models');if(mayImport.value)jobs.value=await aiList('/api/v1/ai/import-jobs');if(route.query.modelId){const m=models.value.find(m=>m.modelId===route.query.modelId);if(m)await select(m)}}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function select(m:AIRecord){error.value='';plan.value=undefined;binding.value=undefined;peerId.value='';try{selected.value=await api('/api/v1/device-models/'+enc(m.modelId));detailTab.value='overview';if(can('gatt:manage'))peers.value=await aiList('/api/v1/ble-peers')}catch(e){error.value=errorText(e)}}
function go(path:string){if(selected.value)router.push({path,query:{modelId:selected.value.modelId}})}
async function bind(){if(!selected.value?.parserRef||!peerId.value)return;busy.value=true;error.value='';try{const peer=peers.value.find(p=>p.peerId===peerId.value);if(!peer||!can('gatt:manage',peer.scopeId))throw new Error('当前对端不在可管理范围');await ElMessageBox.confirm('将为 '+peer.displayName+' 创建到 '+selected.value.modelName+' 的不可变协议绑定。已有规则包不会自动更新。','确认协议绑定',{confirmButtonText:'创建绑定',cancelButtonText:'返回'});binding.value=await api('/api/v1/protocol-bindings','POST',{peerId:peerId.value,parserId:selected.value.parserRef.parserId,parserVersion:selected.value.parserRef.version,modelId:selected.value.modelId,modelVersion:selected.value.version});ElMessage.success('绑定已创建；请在规则包中引用并验证')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function preparePlan(){if(!selected.value)return;busy.value=true;error.value='';try{plan.value=await api('/api/v1/ai/apply-plans','POST',{modelId:selected.value.modelId,sourceContext:{pageId:'P24',returnTo:'/device-models'}})}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function confirmPlan(){if(!plan.value)return;busy.value=true;error.value='';try{plan.value=await api('/api/v1/ai/apply-plans/'+enc(plan.value.planId)+'/executions','POST',{confirmed:true});ElMessage.success('应用参数已确认；请选择下面的目标页面完成现场配置')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><h1>型号模板库</h1><p>一份协议资料形成可复用模板；同型号设备只需选择现场身份和范围。</p></div><div class="toolbar"><el-button @click="load" :loading="loading">刷新</el-button><AiImportLauncher label="导入设备资料" primary/></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="已发布型号" name="models"><section class="panel"><div class="toolbar"><el-input v-model="query" clearable placeholder="搜索厂家、型号、版本"/></div><el-table :data="visible" v-loading="loading" highlight-current-row @row-click="select" empty-text="暂无已发布模板；可先导入资料并完成审阅验证"><el-table-column label="型号 / 厂家" min-width="200"><template #default="{row}"><el-button link type="primary" @click.stop="select(row)">{{row.modelName}}</el-button><div class="muted">{{row.manufacturer||'未提供厂家'}}</div></template></el-table-column><el-table-column prop="version" label="模板版本" width="120"/><el-table-column prop="firmwareRange" label="适用固件" min-width="150"/><el-table-column label="功能" min-width="180"><template #default="{row}"><div class="template-tags"><el-tag v-if="row.parserRef">数据解析</el-tag><el-tag v-if="row.content?.connectionSpec" type="info">GATT 操作</el-tag><el-tag v-if="row.content?.mappingSpec" type="info">字段映射</el-tag></div></template></el-table-column><el-table-column label="验证等级" min-width="145"><template #default="{row}">{{verificationLabel(row.verificationLevel)}}</template></el-table-column><el-table-column label="发布时间" min-width="165"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column></el-table><p class="muted">模板版本不可覆盖。“样例已验证”表示离线样例通过，不代表所有设备与固件都已实测。</p></section></el-tab-pane>
<el-tab-pane v-if="mayImport" label="导入任务与草稿" name="jobs"><section class="panel"><el-table :data="jobs" empty-text="暂无导入任务"><el-table-column label="资料任务" min-width="220"><template #default="{row}"><el-button link type="primary" @click="router.push('/import-jobs/'+row.jobId)">{{taskLabels[row.taskKind]||row.taskKind}}</el-button><div class="mono muted">{{row.jobId}}</div></template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}">{{jobLabels[row.state]||row.state}}</template></el-table-column><el-table-column prop="phase" label="阶段"/><el-table-column label="最近更新" min-width="180"><template #default="{row}">{{dateTime(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link @click="router.push('/import-jobs/'+row.jobId)">继续审阅</el-button></template></el-table-column></el-table></section></el-tab-pane></el-tabs>
<el-drawer :model-value="!!selected" @update:model-value="v=>{if(!v)selected=undefined}" :title="selected?.modelName||'型号详情'" size="min(960px, 97vw)">
<template v-if="selected"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="toolbar"><el-tag>{{selected.version}}</el-tag><el-tag type="info">{{verificationLabel(selected.verificationLevel)}}</el-tag><span class="muted">不可变版本</span></div><el-tabs v-model="detailTab">
<el-tab-pane label="概述与应用" name="overview"><el-descriptions :column="1" border><el-descriptions-item label="厂家">{{selected.manufacturer||'未提供'}}</el-descriptions-item><el-descriptions-item label="适用固件">{{selected.firmwareRange||'尚未限定，请核对现场固件'}}</el-descriptions-item><el-descriptions-item label="资源范围">{{selected.scopeId}}</el-descriptions-item><el-descriptions-item label="解析器">{{selected.parserRef?selected.parserRef.parserId+' @ '+selected.parserRef.version:'无解析器'}}</el-descriptions-item></el-descriptions><h3 class="mt">应用到现场</h3><div class="toolbar"><el-button v-if="selected.content?.connectionSpec&&can('gatt:execute')" @click="go('/gatt-connections')">按模板连接或操作</el-button><el-button v-if="selected.content?.connectionSpec&&can('gatt:manage')" @click="go('/auto-connect-rules')">创建自动连接规则</el-button><el-button v-if="selected.parserRef&&can('parser:test')" @click="go('/parsers')">试算解析器</el-button><el-button v-if="selected.parserRef&&can('rule:write','scope_instance')" @click="go('/rule-bundles')">创建解析规则</el-button><el-button v-if="can('profile:write')" :loading="busy" @click="preparePlan">预览应用计划</el-button></div><p class="muted">上述入口带入固定版本参数。实际连接、写入、规则保存及激活均在对应页面确认。</p>
<section v-if="plan" class="plan-box"><h3>待应用步骤</h3><ol><li v-for="(step,i) in plan.steps" :key="i">{{step.label||step.kind}}<span class="muted"> · {{step.destination}}</span></li></ol><el-button v-if="plan.state==='PREPARED'" @click="confirmPlan" :loading="busy">确认计划参数</el-button><el-tag v-else type="success">参数已确认，待在业务页面应用</el-tag></section>
<section v-if="selected.parserRef&&can('gatt:manage')" class="plan-box"><h3>绑定实际从设备</h3><el-select v-model="peerId" filterable placeholder="选择已登记的静态对端" style="width:100%"><el-option v-for="p in peers" :key="p.peerId" :label="p.displayName+' · '+p.deviceAddress" :value="p.peerId" :disabled="p.state!=='ACTIVE'||!can('gatt:manage',p.scopeId)"/></el-select><p class="muted">协议绑定用于区分同一网关上的不同型号。创建绑定不会自动切换已激活规则。</p><el-button :disabled="!peerId" :loading="busy" @click="bind">创建协议绑定</el-button><p v-if="binding" class="mono">绑定 {{binding.bindingId}}</p></section></el-tab-pane>
<el-tab-pane label="解析字段" name="parser"><el-table :data="selected.content?.parserSpec?.fields||[]" empty-text="此模板不包含解析器"><el-table-column prop="name" label="字段"/><el-table-column prop="offset" label="偏移" width="80"/><el-table-column prop="type" label="类型"/><el-table-column prop="endian" label="字节序"/><el-table-column prop="scale" label="倍率"/><el-table-column prop="unit" label="单位"/></el-table><p class="muted">输入类型 {{selected.content?.parserSpec?.inputKind||'—'}}</p></el-tab-pane>
<el-tab-pane label="连接与映射" name="connection"><pre class="code-block">{{pretty({connectionSpec:selected.content?.connectionSpec,mappingSpec:selected.content?.mappingSpec})}}</pre></el-tab-pane><el-tab-pane label="样例与证据" name="evidence"><el-alert v-if="selected.evidenceRestricted" title="当前角色只能查看模板功能，原始样例和资料依据需要文档读取权限。" type="info" :closable="false"/><h3>独立测试样例</h3><pre class="code-block">{{pretty(selected.content?.tests||[])}}</pre><h3>配置依据</h3><pre class="code-block">{{pretty(selected.content?.sources||[])}}</pre></el-tab-pane>
</el-tabs></template></el-drawer></div></template>
<style scoped>.template-tags{display:flex;gap:6px;flex-wrap:wrap}.mt{margin-top:24px}.plan-box{padding:18px 0;border-top:1px solid #e0e7eb;margin-top:20px}.plan-box li{line-height:1.8}pre{max-width:100%;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
